-- Facility page details (chips, fact rows, highlights, enquiry wording) move from code into the database, editable in the House.
ALTER TABLE "Facility" ADD COLUMN "details" JSONB;

-- Carry over what the website showed until now, so nothing changes for visitors.
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Breakfast from 6:30"}},{"text":{"en":"Dinner until 21:30"}},{"text":{"en":"Local Fresh Produce"}},{"text":{"en":"Packed Trail Lunches"}}],"specs":[{"icon":"clock","label":{"en":"Service Hours"},"value":{"en":"Breakfast 06:30–10:30 · Dinner until 21:30"}},{"icon":"users","label":{"en":"Dining Capacity"},"value":{"en":"40 seats indoor with mountain ridge vistas"}},{"icon":"utensils","label":{"en":"Cuisine & Sourcing"},"value":{"en":"Farm-to-table slope vegetables, fresh river trout, local matooke"}},{"icon":"coffee","label":{"en":"Artisan Coffee"},"value":{"en":"Single-origin 1,900m Mount Elgon Arabica French press"}},{"icon":"gift","label":{"en":"Stay Inclusions"},"value":{"en":"Full country breakfast included with bed & breakfast bookings"}},{"icon":"backpack","label":{"en":"Hiking & Excursions"},"value":{"en":"Packed lunches arranged the night before for Sipi trail walks"}}],"highlights":[{"text":{"en":"Early service from 6:30 AM to catch the magical morning light over Sipi Falls"}},{"text":{"en":"Fresh river trout sourced directly as it arrives from the mountain streams"}},{"text":{"en":"Seasonal slope ingredients: matooke, slow-cooked highland beans, and fresh market greens"}},{"text":{"en":"Mount Elgon Arabica coffee harvested and roasted within the district"}},{"text":{"en":"Custom group menus and packed trail rations prepared for hikers and athletes"}}],"badge":{"en":"Open Daily"},"note":{"en":"Breakfast is included on all bed-and-breakfast room bookings. Walk-in dining is warmly welcomed subject to table availability."},"enquireLabel":{"en":"Inquire About Dining & Tables"},"enquireIntent":"STAY","whatsappText":"Hello Reberon Hotel, I would like to inquire about dining, breakfast hours, or reserve a table at the Restaurant."}'::jsonb WHERE lower("slug") = 'restaurant' AND "details" IS NULL;
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Capacity: 40 Guests"}},{"text":{"en":"HD Screen & Audio"}},{"text":{"en":"Ridge Windows"}},{"text":{"en":"Event Packages"}}],"specs":[{"icon":"users","label":{"en":"Event Capacity"},"value":{"en":"40 theatre style · 24 around tables · 50 reception"}},{"icon":"presentation","label":{"en":"Audio & Visual"},"value":{"en":"High-definition projection screen & wireless speech audio"}},{"icon":"wifi","label":{"en":"Connectivity"},"value":{"en":"Dual high-speed Wi-Fi and universal workstation power outlets"}},{"icon":"mountain","label":{"en":"Ridge Setting"},"value":{"en":"Panoramic escarpment windows overlooking Mount Elgon"}},{"icon":"coffee","label":{"en":"Catering Breaks"},"value":{"en":"Highland coffee, teas, fresh pastries, and seated lunches"}},{"icon":"door-open","label":{"en":"Terrace Access"},"value":{"en":"Direct breakout doors to the open-air garden terrace"}}],"highlights":[{"text":{"en":"Versatile layout: theatre seating for 40, boardroom configuration for 24, or clear floor for private receptions"}},{"text":{"en":"Modern presentation technology: high-definition screen, crisp public-address audio, and HDMI/wireless casting"}},{"text":{"en":"Floor-to-ceiling windows framing the Mount Elgon ridge to give delegates natural daylight and refreshing mountain air"}},{"text":{"en":"Seamless breakout space opening directly onto the scenic garden terrace for morning coffee and sunset chats"}},{"text":{"en":"Tailored catering packages from continuous artisan coffee stations to three-course plated executive lunches"}},{"text":{"en":"Combined room blocks: reserve accommodation for your delegates alongside hall bookings under a single quotation"}}],"badge":{"en":"Meetings & Events"},"note":{"en":"Fast turnaround: receive a tailored one-page quote within 24 hours. Groups can hold suite blocks alongside the hall."},"enquireLabel":{"en":"Request Event Proposal & Quote"},"enquireIntent":"EVENT","whatsappText":"Hello Reberon Hotel, I would like to request availability and a proposal for hosting an event, meeting, or workshop in The Hall."}'::jsonb WHERE lower("slug") = 'hall' AND "details" IS NULL;
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Inside Compound"}},{"text":{"en":"24/7 Gate Guarded"}},{"text":{"en":"Night Floodlit"}},{"text":{"en":"Minibus Space"}}],"specs":[{"icon":"shield-check","label":{"en":"Security & Access"},"value":{"en":"Gated private perimeter with 24/7 stationed watch"}},{"icon":"car","label":{"en":"Vehicle Capacity"},"value":{"en":"15+ saloon cars, SUVs, and safari 4x4 minibuses"}},{"icon":"sun","label":{"en":"Lighting"},"value":{"en":"Full compound floodlighting throughout the night"}},{"icon":"route","label":{"en":"Road Access"},"value":{"en":"1 km murram spur off the Mbale–Kapchorwa tarmac highway"}},{"icon":"clock","label":{"en":"Arrivals"},"value":{"en":"Late night arrival reception and lighted vehicle escort"}}],"highlights":[{"text":{"en":"Secure enclosed compound protected round-the-clock by dedicated gate personnel"}},{"text":{"en":"Spacious paved parking bays accommodating family saloons, safari cruisers, and tour coasters"}},{"text":{"en":"Bright perimeter and flood illumination ensuring safety at all nighttime hours"}},{"text":{"en":"Safe turning bay allowing easy maneuvering for large tour vans and minibuses"}},{"text":{"en":"Driver rest facilities and wash assistance available upon request at front desk"}}],"badge":{"en":"Secure & Complimentary"},"note":{"en":"The 1km access road from the highway is standard murram: easily handled by saloon cars during dry weather, take gentle care during rains."},"enquireLabel":{"en":"Inquire About Parking & Access"},"enquireIntent":"GENERAL","whatsappText":"Hello Reberon Hotel, I would like to inquire about road conditions, vehicle parking, or arrivals for my vehicle."}'::jsonb WHERE lower("slug") = 'parking' AND "details" IS NULL;
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Grid + Solar Array"}},{"text":{"en":"Lithium Battery Storage"}},{"text":{"en":"Instant Failover"}},{"text":{"en":"24/7 Hot Water"}}],"specs":[{"icon":"zap","label":{"en":"Solar Capacity"},"value":{"en":"Rooftop photovoltaic solar array with intelligent inverter"}},{"icon":"battery-charging","label":{"en":"Battery Reserve"},"value":{"en":"High-capacity lithium battery bank for silent nighttime backup"}},{"icon":"plug","label":{"en":"Failover Response"},"value":{"en":"Instant automated changeover during national grid interruptions"}},{"icon":"wifi","label":{"en":"Always Connected"},"value":{"en":"Continuous uninterrupted power to Wi-Fi routers and room sockets"}},{"icon":"shower-head","label":{"en":"Hot Showers"},"value":{"en":"Dedicated solar-thermal & electric water heating in all bathrooms"}}],"highlights":[{"text":{"en":"Dual-layer hybrid clean energy system combining national grid, rooftop solar, and lithium battery storage"}},{"text":{"en":"Automatic instant switchover so room lights, workstation sockets, and Wi-Fi continue without a flicker during grid outages"}},{"text":{"en":"Heavy-duty emergency standby generator maintained for prolonged regional transmission outages"}},{"text":{"en":"High-pressure hot showers guaranteed in every guest room, morning and night"}},{"text":{"en":"Work-friendly sanctuary: charge cameras, laptops, and drones reliably at 1,900m altitude"}}],"badge":{"en":"100% Redundant Backup"},"note":{"en":"Ideal for digital nomads, mountain runners recording GPS sessions, and photographers backing up daily expedition footage."},"enquireLabel":{"en":"Ask About Work & Power Setup"},"enquireIntent":"GENERAL","whatsappText":"Hello Reberon Hotel, I have a question regarding power reliability, remote work setup, or charging equipment at the hotel."}'::jsonb WHERE lower("slug") = 'power' AND "details" IS NULL;
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Deep Borehole"}},{"text":{"en":"UV Filtered"}},{"text":{"en":"Hot Water 24/7"}},{"text":{"en":"Zero Single-Use Plastic"}}],"specs":[{"icon":"droplets","label":{"en":"Water Source"},"value":{"en":"Dedicated deep volcanic rock borehole on the compound"}},{"icon":"shield-check","label":{"en":"Purification"},"value":{"en":"Multi-stage sediment filtration and ultraviolet water treatment"}},{"icon":"shower-head","label":{"en":"Hot Water Supply"},"value":{"en":"High-pressure continuous hot water to all suites all day"}},{"icon":"coffee","label":{"en":"Drinking Water"},"value":{"en":"Complimentary purified glass-bottled water replenished daily"}},{"icon":"trees","label":{"en":"Eco Commitment"},"value":{"en":"Zero single-use plastic water bottles purchased or discarded"}}],"highlights":[{"text":{"en":"Self-sufficient natural water supply tapped directly from deep Mount Elgon volcanic aquifers"}},{"text":{"en":"Rigorous multi-stage filtration and UV purification ensuring clean, safe, soft water throughout the property"}},{"text":{"en":"Generous high-pressure hot water in every suite bathroom, soothing tired muscles after trail hikes"}},{"text":{"en":"Eco-conscious hospitality: refillable glass carafes in all rooms eliminate single-use plastic waste"}},{"text":{"en":"Pure natural water used in all restaurant cooking and artisan coffee brewing"}}],"badge":{"en":"Borehole & UV Purified"},"note":{"en":"Fresh drinking water is provided complimentary in every room and refilled daily by housekeeping."},"enquireLabel":{"en":"Ask Front Desk About Amenities"},"enquireIntent":"GENERAL","whatsappText":"Hello Reberon Hotel, I would like to inquire about suite amenities, water supply, or guest provisions."}'::jsonb WHERE lower("slug") = 'water' AND "details" IS NULL;
UPDATE "Facility" SET "details" = '{"tags":[{"text":{"en":"Mountain Ridge Views"}},{"text":{"en":"Morning Mist Coffee"}},{"text":{"en":"Evening Wood Firepit"}},{"text":{"en":"Birdwatching Vistas"}}],"specs":[{"icon":"mountain","label":{"en":"Panoramic Elevation"},"value":{"en":"1,900m ASL escarpment facing the slopes of Mount Elgon"}},{"icon":"coffee","label":{"en":"Morning Ritual"},"value":{"en":"Artisan Arabica coffee as dawn breaks and the valley mist clears"}},{"icon":"flame","label":{"en":"Evening Firepit"},"value":{"en":"Cozy open wood fire pit lit when highland mountain chill arrives"}},{"icon":"utensils","label":{"en":"Outdoor Dining"},"value":{"en":"Al-fresco breakfast, sundowner drinks, and fireside tapas"}},{"icon":"trees","label":{"en":"Nature Viewing"},"value":{"en":"Canopy birdwatching overlooking indigenous trees and flowers"}}],"highlights":[{"text":{"en":"Spacious elevated terrace situated between the main dining room and landscaped hillside gardens"}},{"text":{"en":"Direct east-facing orientation catching early morning alpine sun rays over Mount Elgon"}},{"text":{"en":"Open wood hearth and firepit crackling nightly to warm guests against crisp highland breezes"}},{"text":{"en":"Relaxed outdoor lounge seating for morning contemplation, afternoon reading, or twilight cocktails"}},{"text":{"en":"Stunning dark-sky stargazing opportunities with zero light pollution from major cities"}}],"badge":{"en":"Being Built · Opening Soon"},"note":{"en":"Currently receiving its finishing stone accents and artisan firepit hearth. Walk-in guests are welcome to enjoy the view."},"enquireLabel":{"en":"Inquire About Stays & Sundowners"},"enquireIntent":"STAY","whatsappText":"Hello Reberon Hotel, I would like to inquire about the Garden Terrace, sunset drinks, or upcoming stays."}'::jsonb WHERE lower("slug") = 'terrace' AND "details" IS NULL;
